#ifdef USE_CUDA_NAMES
    function hipblasDtrsv_(handle,uplo,transA,diag,n,AP,lda,x,incx) bind(c, name="cublasDtrsv_v2")
#else
    function hipblasDtrsv_(handle,uplo,transA,diag,n,AP,lda,x,incx) bind(c, name="hipblasDtrsv")
