  !>     @param[in]
  !>     ldinvA    [int]
  !>               specifies the leading dimension of each invA_i.
  !>     @param[in]
  !>     stride_invA  [hipblasStride]
  !>                  "batch stride invA": stride from the start of one invA_i matrix to the next
  !>                  invA_(i + 1).
  !>     @param[in]
  !>     batchCount  [int]
